<script lang="ts">
  import {onMount} from 'svelte';import {listen} from '@tauri-apps/api/event';import {getCurrentWindow} from '@tauri-apps/api/window';
  import {rpc,defaults,errorText,type Appearance,type Connection,type Profile} from './lib/api';import {ask,notify,notice,dialog,closeGuards} from './lib/ui';import {downloadState,downloadCompletion,watchDownloads,refreshDownloads,running} from './lib/download-monitor';
  import ConnectionScreen from './components/ConnectionScreen.svelte';import WindowFrame,{type WindowModel} from './components/WindowFrame.svelte';import TerminalWindow from './components/TerminalWindow.svelte';import FileManagerWindow from './components/FileManagerWindow.svelte';import TextEditorWindow from './components/TextEditorWindow.svelte';import BrowserWindow from './components/BrowserWindow.svelte';import DownloadManager from './components/DownloadManager.svelte';import DownloadDestinationPicker from './components/DownloadDestinationPicker.svelte';import AppearanceSettings from './components/AppearanceSettings.svelte';import Dialog from './components/Dialog.svelte';import Icon from './components/Icon.svelte';
  let profiles=$state<Profile[]>([]);let connection=$state<Connection|null>(null);let appearance=$state<Appearance>({...defaults});let windows=$state<WindowModel[]>([]);let focused=$state('');let launcher=$state(false);let clock=$state(new Date());let online=$state(true);let destination=$state<{url:string;filename:string;offerId?:string;localToken?:string;browserRequest?:boolean}|null>(null);let downloadQueue=$state<Array<{url:string;filename:string;offerId?:string;localToken?:string;browserRequest?:boolean}>>([]);let downloadRevision=$state(0);let initialized=$state(false);let initError=$state('');let z=1;let appearanceTimer:ReturnType<typeof setTimeout>;
  $effect(()=>{if(connection?.profile.id)return watchDownloads();});
  $effect(()=>{const foreground=windows.find(w=>w.id===focused&&w.kind==='browser'&&!w.minimized);void rpc('browser_desktop',{owner:foreground?.id||null,blocked:!!destination||!!$dialog||launcher||!!$downloadCompletion||!connection}).catch(()=>{});});
  const activeDownloads=$derived($downloadState.jobs.filter(running).length);
  function enqueueDownload(request:{url:string;filename:string;offerId?:string;localToken?:string;browserRequest?:boolean}){if(!destination)destination=request;else if(downloadQueue.length<20)downloadQueue=[...downloadQueue,request];else {notify('The download request queue is full. Finish or cancel existing requests first.');if(request.localToken)void rpc('download_local_discard',{token:request.localToken}).catch(()=>{});}}
  function closeDestination(){destination=downloadQueue[0]||null;downloadQueue=downloadQueue.slice(1);}
  const apps=[{kind:'terminal',title:'Terminal',subtitle:'A direct line to your server'},{kind:'browser',title:'Browser',subtitle:'Browse here, download there'},{kind:'files',title:'File Manager',subtitle:'Your remote filesystem'},{kind:'downloads',title:'Downloads',subtitle:'Files on their way to your server'},{kind:'settings',title:'Appearance',subtitle:'Make yourself at home'}];
  function open(kind:string,path?:string){launcher=false;const app=apps.find(a=>a.kind===kind);if(kind==='downloads'||kind==='settings'){const existing=windows.find(w=>w.kind===kind);if(existing){focus(existing.id);return;}}const id=crypto.randomUUID();const size=kind==='settings'?{width:620,height:650}:{width:Math.min(1000,innerWidth-100),height:Math.min(640,innerHeight-150)};const offset=(windows.length%5)*26;windows=[...windows,{id,kind,title:kind==='editor'?path!.split('/').pop()!:app?.title||kind,x:Math.min(70+offset,innerWidth-size.width-8),y:Math.min(45+offset,innerHeight-size.height-80),...size,z:++z,minimized:false,maximized:false,path}];focused=id;}
  function focus(id:string){launcher=false;focused=id;windows=windows.map(w=>w.id===id?{...w,z:++z,minimized:false}:w);}
  function update(id:string,patch:Partial<WindowModel>){windows=windows.map(w=>w.id===id?{...w,...patch}:w);}
  async function close(id:string){const guard=closeGuards.get(id);if(guard&&!await guard())return;windows=windows.filter(w=>w.id!==id);if(focused===id)focused=[...windows].filter(w=>!w.minimized).sort((a,b)=>b.z-a.z)[0]?.id||'';}
  function minimize(id:string){update(id,{minimized:true});focused=[...windows].filter(w=>!w.minimized).sort((a,b)=>b.z-a.z)[0]?.id||'';}
  function changeAppearance(value:Appearance){appearance=value;clearTimeout(appearanceTimer);appearanceTimer=setTimeout(()=>{void rpc('appearance',value).catch(notify);},250);}
  async function disconnect(){for(const guard of closeGuards.values())if(!await guard())return;try{await rpc('appearance',appearance);await rpc('disconnect',{});windows=[];connection=null;destination=null;downloadQueue=[];launcher=false;}catch(e){notify(e);}}
  async function newDownload(url=''){const input=await ask('Download a direct URL','Paste a public HTTP/HTTPS file URL. The remote server will fetch it without browser cookies.',{input:url,confirm:'Choose destination'});if(!input)return;try{const u=new URL(input);if(!['http:','https:'].includes(u.protocol))throw new Error('Only HTTP/HTTPS direct URLs are supported.');enqueueDownload({url:input,filename:decodeURIComponent(u.pathname.split('/').pop()||'download')});}catch(e){notify(e);}}
  onMount(()=>{
    const unlisten:Array<()=>void>=[];let disposed=false;let healthBusy=false;
    void getCurrentWindow().onCloseRequested(async event=>{event.preventDefault();for(const guard of closeGuards.values())if(!await guard())return;try{if(initialized)await rpc('appearance',appearance);if(connection)await rpc('disconnect',{});await getCurrentWindow().destroy();}catch(e){notify(e);}}).then(off=>{if(disposed)off();else unlisten.push(off);});
    void (async()=>{try{const init=await rpc('initialize',{});profiles=init.profiles;appearance={...defaults,...init.appearance};initialized=true;unlisten.push(await listen<{url:string;filename:string;supported:boolean;localToken?:string;offerId?:string}>('download-request',e=>{if(!connection)return;if(!e.payload.supported&&!e.payload.localToken){notify('This download cannot be delegated. Blob URLs and browser session requests require a direct HTTP/HTTPS link. No local download was saved.');return;}enqueueDownload({url:e.payload.url,filename:e.payload.filename,offerId:e.payload.offerId,localToken:e.payload.localToken,browserRequest:true});launcher=false;}));unlisten.push(await listen<string>('settings-warning',e=>notify(e.payload)));if(disposed)unlisten.forEach(f=>f());}catch(e){initError=errorText(e);}})();
    const tick=setInterval(()=>clock=new Date(),1000);const health=setInterval(async()=>{if(!connection||healthBusy)return;healthBusy=true;try{await rpc('health',{});online=true;}catch{online=false;}finally{healthBusy=false;}},10000);
    const resize=()=>windows=windows.map(w=>({...w,width:Math.min(w.width,innerWidth-16),height:Math.min(w.height,innerHeight-84),x:Math.max(8,Math.min(w.x,innerWidth-Math.min(w.width,innerWidth-16)-8)),y:Math.max(8,Math.min(w.y,innerHeight-Math.min(w.height,innerHeight-84)-76))}));window.addEventListener('resize',resize);
    return()=>{disposed=true;clearInterval(tick);clearInterval(health);clearTimeout(appearanceTimer);unlisten.forEach(f=>f());window.removeEventListener('resize',resize);};
  });
</script>
<div class="application" data-theme={appearance.theme} style:--accent={appearance.accent} style:--desktop={appearance.background} style:--taskbar={appearance.taskbar} style:--window={appearance.window}>
{#if !initialized}<div class="startup">{#if initError}<Icon name="close" size={32}/><h2>Unable to initialize</h2><p>{initError}</p>{:else}<span class="spinner"></span><p>Opening your workspace…</p>{/if}</div>
{:else if !connection}<ConnectionScreen {profiles} connected={c=>{connection=c;online=true;}} save={p=>profiles=p}/>
{:else}
  <main class="desktop" style:background-image={appearance.wallpaper?`url("${appearance.wallpaper}")`:undefined}>
    <div class="desktop-watermark"><div class="eyebrow">YOUR REMOTE WORKSPACE</div><h1>{connection.profile.name}</h1><p>{connection.profile.username}@{connection.profile.host} <span>•</span> {connection.remote.platform}, within reach.</p></div>
    <div class="desktop-shortcuts">{#each apps.slice(0,3) as app}<button onclick={()=>open(app.kind)}><span class="desktop-shortcut-icon"><Icon name={app.kind} size={30}/></span>{app.title}</button>{/each}</div>
    {#each windows as w(w.id)}<WindowFrame window={w} active={focused===w.id} onfocus={()=>{if(focused!==w.id||launcher)focus(w.id);}} onclose={()=>close(w.id)} onminimize={()=>minimize(w.id)} onmaximize={()=>update(w.id,{maximized:!w.maximized})} onchange={patch=>update(w.id,patch)}>
      {#if w.kind==='terminal'}<TerminalWindow id={w.id} cwd={w.path} active={focused===w.id&&!w.minimized}/>
      {:else if w.kind==='files'}<FileManagerWindow initial={w.path||connection.home} openEditor={p=>open('editor',p)} openTerminal={p=>open('terminal',p)}/>
      {:else if w.kind==='editor'}<TextEditorWindow id={w.id} path={w.path!} active={focused===w.id&&!w.minimized}/>
      {:else if w.kind==='browser'}<BrowserWindow id={w.id} active={focused===w.id&&!w.minimized} geometry={`${w.x},${w.y},${w.width},${w.height},${w.maximized}`} modal={!!destination||!!$dialog||launcher||!!$downloadCompletion} requestDownload={newDownload} openDownloads={()=>open('downloads')} downloadCount={activeDownloads}/>
      {:else if w.kind==='downloads'}<DownloadManager openFolder={p=>open('files',p)} newDownload={(url,name)=>{if(url)enqueueDownload({url,filename:name||'download'});else void newDownload();}} revision={downloadRevision}/>
      {:else if w.kind==='settings'}<AppearanceSettings settings={appearance} change={changeAppearance}/>{/if}
    </WindowFrame>{/each}
    {#if !online}<div class="connection-lost"><Icon name="server"/><span>SSH connection lost. Remote downloads may still be running.</span><button onclick={async()=>{await disconnect();}}>Reconnect</button></div>{/if}
    {#if launcher}<section class="app-launcher"><header><span class="avatar">{connection.profile.username.slice(0,1).toUpperCase()}</span><div><strong>{connection.profile.username}</strong><small>{connection.profile.host}</small></div><span class="spacer"></span><span class="status-dot"></span></header><div class="eyebrow">APPLICATIONS</div>{#each apps as app}<button onclick={()=>open(app.kind)}><span class="launcher-icon"><Icon name={app.kind} size={24}/></span><span>{app.title}<small>{app.subtitle}</small></span><span class="spacer"></span><span class="muted">›</span></button>{/each}<footer><span>SSH Virtual Desktop</span><button title="Disconnect" onclick={disconnect}><Icon name="power" size={18}/> Disconnect</button></footer></section>{/if}
    <nav class="taskbar" aria-label="Desktop taskbar"><button class="launcher-button" class:chosen={launcher} title="Application launcher" onclick={()=>launcher=!launcher}><Icon name="launcher" size={22}/></button><span class="taskbar-divider"></span>{#each apps.slice(0,3) as app}<button class="taskbar-shortcut" title={`New ${app.title}`} onclick={()=>open(app.kind)}><Icon name={app.kind} size={24}/><span class="running-dots">{#each windows.filter(w=>w.kind===app.kind).slice(0,4) as item}<i class:current={focused===item.id}></i>{/each}</span></button>{/each}<span class="taskbar-divider"></span><div class="taskbar-windows">{#each windows as w}<button class:current={focused===w.id&&!w.minimized} title={w.title} onclick={()=>{if(focused===w.id&&!w.minimized)minimize(w.id);else focus(w.id);}}><Icon name={w.kind==='editor'?'file':w.kind} size={16}/><span>{w.title}</span></button>{/each}</div><button class="connection-indicator" title={`${connection.profile.username}@${connection.profile.host}`} onclick={()=>launcher=!launcher}><span class="status-dot" class:offline={!online}></span><span>{online?'Connected':'Offline'}</span></button><button class="taskbar-clock" onclick={()=>open('settings')}><strong>{clock.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</strong><span>{clock.toLocaleDateString([],{month:'short',day:'numeric'})}</span></button></nav>
  </main>
{/if}
{#if destination&&connection}{#key destination}<DownloadDestinationPicker home={connection.home} url={destination.url} filename={destination.filename} offerId={destination.offerId} localToken={destination.localToken} browserRequest={destination.browserRequest} onclose={closeDestination} onstarted={()=>{downloadRevision++;void refreshDownloads();open('downloads');notify('Download started. Its transfer mode is shown in Downloads.');}}/>{/key}{/if}
<Dialog/>{#if $downloadCompletion&&connection}<div class="download-completion" role="status"><Icon name="check" size={18}/><span>Downloaded <strong>{$downloadCompletion.filename}</strong></span><button onclick={()=>{if($downloadCompletion)open('files',$downloadCompletion.directory);downloadCompletion.set(null);}}>Open Folder</button><button class="icon-button" aria-label="Dismiss download notification" onclick={()=>downloadCompletion.set(null)}><Icon name="close" size={15}/></button></div>{/if}{#if $notice}<div class="toast" role="status">{$notice}<button class="icon-button" aria-label="Dismiss notification" onclick={()=>notice.set('')}><Icon name="close" size={16}/></button></div>{/if}
</div>
